export class Book {
    constructor(id, title, author, year, isBorrowed = false) {
        this.id = id;
        this.title = title;
        this.author = author;
        this.year = year;
        this.isBorrowed = isBorrowed;
    }
    getSummary() {
        return `${this.title} — ${this.author} (${this.year})`;
    }
    borrow() {
        this.isBorrowed = true;
    }
    returned() {
        this.isBorrowed = false;
    }
}
export class User {
    constructor(id, name, email, borrowedIds = []) {
        this.id = id;
        this.name = name;
        this.email = email;
        this.borrowedIds = borrowedIds;
    }
    canBorrow() {
        return this.borrowedIds.length < 3;
    }
    borrowBook(bookId) {
        this.borrowedIds.push(bookId);
    }
    returnBook(bookId) {
        this.borrowedIds = this.borrowedIds.filter((id) => id !== bookId);
    }
}
