export class Library {
    constructor(initial = []) {
        this.items = [];
        this.items = initial.slice();
    }
    add(item) {
        this.items.push(item);
    }
    remove(id) {
        this.items = this.items.filter((i) => i.id !== id);
    }
    findById(id) {
        return this.items.find((i) => i.id === id);
    }
    list() {
        return this.items.slice();
    }
    clear() {
        this.items = [];
    }
}
